{
  "name": "@joe-broadhead/opencode-messaging",
  "version": "0.9.7",
  "description": "OpenCode plugin for Messaging agent-to-agent messaging and tasks",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/joe-broadhead/opencode-messaging.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22.15.0"
  },
  "author": "Joe Broadhead",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "a2a",
    "agent-to-agent",
    "messaging"
  ],
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./rpc": "./dist/rpc.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist/index.js",
    "dist/rpc.js",
    "dist/tui.js",
    "dist/third-party-notices.md",
    "skills/opencode-messaging/SKILL.md",
    "assets/icon.svg",
    "views/section.html",
    "docs/*.md",
    "README.md",
    "LICENSE",
    "NOTICE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "gates": "node scripts/gates.mjs",
    "compile": "tsc -b tsconfig.json tsconfig.tui.json && node scripts/build-tui.mjs && node scripts/bundle.mjs",
    "clean": "node scripts/clean.mjs",
    "test": "vitest run",
    "typecheck": "tsc -p tsconfig.test.json",
    "test:host": "node node_modules/vitest/vitest.mjs run --config test/host/vitest.config.ts",
    "test:host:22": "node node_modules/vitest/vitest.mjs run --config test/host-22/vitest.config.ts",
    "golden:update": "MESSAGING_GOLDEN=update vitest run test/golden.test.ts",
    "check:package": "node scripts/check-package.mjs",
    "check:library": "node scripts/check-library.mjs",
    "test:pack": "node --test scripts/pack-checks.test.mjs",
    "check:platforms": "node scripts/check-platforms.mjs",
    "pack:tarball": "node scripts/pack-tarballs.mjs",
    "smoke:pack": "node scripts/smoke-pack.mjs",
    "audit:shipped": "node scripts/audit-shipped.mjs",
    "messaging:bump": "node scripts/messaging-bump.mjs",
    "jelly:update": "node scripts/jelly-declaration.mjs"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5 <2.4.0",
    "@opentui/solid": ">=0.8.0 <0.9",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "@joe-broadhead/messaging": "0.9.7",
    "@opencode/plugin": "2.3.0",
    "@opentui/solid": "0.8.4",
    "@types/node": "22.20.5",
    "babel-preset-solid": "1.9.19",
    "rolldown": "1.3.2",
    "solid-js": "1.9.17",
    "typescript": "5.9.3",
    "uqr": "0.1.3",
    "vitest": "5.1.0",
    "zod": "4.6.7"
  },
  "optionalDependencies": {
    "@joe-broadhead/messaging-bin-darwin-arm64": "0.9.7",
    "@joe-broadhead/messaging-bin-darwin-x64": "0.9.7",
    "@joe-broadhead/messaging-bin-linux-arm64-gnu": "0.9.7",
    "@joe-broadhead/messaging-bin-linux-x64-gnu": "0.9.7",
    "@joe-broadhead/messaging-bin-win32-x64": "0.9.7"
